WITH latest AS (SELECT id, end_date FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY plan ORDER BY start_date DESC NULLS FIRST, id) AS row_num FROM subscriptions) t WHERE row_num = 1) SELECT DATE_TRUNC('YEAR', end_date) AS year_start, DATE_TRUNC('WEEK', end_date) AS week_start, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, COUNT(*) AS cnt, COUNT(DISTINCT id) AS distinct_ids_2, COUNT(DISTINCT id) AS distinct_ids_3 FROM latest GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', end_date), DATE_TRUNC('WEEK', end_date)), (DATE_TRUNC('YEAR', end_date)), ()) ORDER BY cnt
